import{c as s,Q as e,j as a,m as n}from"./chunks/framework.BqPkuuVc.js";const i="/assets/settings-ai-assistants.DACnWZOh.png",o="/assets/settings-ai-assistants-writes.PiKDPUwj.png",k=JSON.parse('{"title":"AI assistants (MCP)","description":"","frontmatter":{},"headers":[],"relativePath":"user/reference/ai-assistants-mcp.md","filePath":"user/reference/ai-assistants-mcp.md"}'),r={name:"user/reference/ai-assistants-mcp.md"};function h(l,t,d,c,p,u){return e(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="ai-assistants-mcp" tabindex="-1">AI assistants (MCP) <a class="header-anchor" href="#ai-assistants-mcp" aria-label="Permalink to &quot;AI assistants (MCP)&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers and timing operators who want to ask an AI assistant questions about a live event.</p><p>meshO Manager can let an AI assistant — Claude, or any other app that speaks the <em>Model Context Protocol</em> (MCP) — read your event and answer questions about it in plain language:</p><blockquote><p><em>Who is still out on course in M21E?</em><em>What are the top three in W21, and is that final yet?</em><em>Anything come in from control 42 in the last ten minutes?</em><em>Why is Carl Mo showing a mispunch — what did he actually punch?</em></p></blockquote><p>This is <strong>switched off by default</strong>. Nothing listens, and no assistant can see anything, until you deliberately turn it on in <strong>Settings → AI assistants</strong>.</p><p><img src="'+i+`" alt="The AI assistants settings page, with both switches off"></p><h2 id="what-an-assistant-can-see" tabindex="-1">What an assistant can see <a class="header-anchor" href="#what-an-assistant-can-see" aria-label="Permalink to &quot;What an assistant can see&quot;">​</a></h2><p>Once connected, an assistant can read:</p><table tabindex="0"><thead><tr><th>It can read</th><th>For example</th></tr></thead><tbody><tr><td>Your events and their status</td><td>&quot;Which events are on this computer?&quot;</td></tr><tr><td>Classes, courses, controls and clubs</td><td>&quot;Which controls are radio controls?&quot;</td></tr><tr><td>How each course is scored, and what completing it takes</td><td>&quot;How many controls does the Scatter class need?&quot;</td></tr><tr><td>The start list</td><td>&quot;Who is entered in W21, and when do they start?&quot;</td></tr><tr><td>Results, ranked per class</td><td>&quot;Top three in M21E?&quot;</td></tr><tr><td>One competitor&#39;s full detail and splits</td><td>&quot;Show me Anna Berg&#39;s splits&quot;</td></tr><tr><td>Radio punches as they arrive</td><td>&quot;Who has passed control 42?&quot;</td></tr><tr><td>Whether a control&#39;s clock is out</td><td>&quot;Is anything wrong with the timing at the finish?&quot;</td></tr><tr><td>Status messages from the dashboard</td><td>&quot;Any warnings on this event?&quot;</td></tr><tr><td>Manager&#39;s own health, and each radio unit</td><td>&quot;Is Prime connected?&quot;</td></tr><tr><td>Where runners lost time, per leg</td><td>&quot;Where did Anna lose time?&quot;</td></tr><tr><td>Leg distances for a course</td><td>&quot;How long is the leg to control 42?&quot;</td></tr><tr><td>The results as an IOF XML export</td><td>&quot;Export the results for the federation&quot;</td></tr><tr><td>The results or start list as Orienteering JSON</td><td>&quot;Export the start list as JSON so I can send it on&quot;</td></tr><tr><td>Carnivals and knock-outs, and the standings across their stages</td><td>&quot;Who leads the 3-Days after day 2?&quot;</td></tr><tr><td><strong>This event&#39;s change history</strong></td><td>&quot;Who changed Anna&#39;s status, and when?&quot;</td></tr></tbody></table><p>That last one is worth a moment. The change history is the event&#39;s audit trail: every edit, who or what made it, and the before and after values. It is the most revealing thing on the list — an assistant reading it can see the whole editing history of the event, not just its current state.</p><p>The scoring entry matters most at a <strong>scatter</strong> event, where a course is &quot;any 6 of the controls out there&quot; rather than a sequence. Every scatter course covers the same controls, so what tells one class from another is the number it asks for — and a mis-punch means a runner came back with too few, not that they missed a particular control. An assistant is told both, so it explains a mis-punch there as &quot;visited 4 of the 6 required&quot; rather than naming a control nobody was sent to.</p><p>Multi-stage competitions sit above the events rather than inside one, so an assistant sees both: a carnival and its overall standings, and the ordinary events that are its stages. Two things it is told, because both are easy to get wrong from the numbers alone — that a total is only a <em>time</em> when the carnival is scored on total time (under a points method the same figure is a score, and reading it as a time would be nonsense), and that a knock-out has no overall total at all, because adding up rounds run on different courses would put a fast B final ahead of the A final.</p><p>The clock entry is there because a control station that is running an hour fast produces times that look completely normal. Where you have a meshO Control radio at a control, the Manager works out how far its clock is out, and an assistant is told the same thing — including how much of that error you have already corrected, so it reads a control you have fixed as fixed. Controls with no radio at them report nothing about their clock either way.</p><p>It does <strong>not</strong> get your settings, your access PIN, other events&#39; data beyond the list above, or anything outside the event data it is asked about.</p><blockquote><p><strong>Your event data stays on your computer</strong> in the sense that MCP itself never uploads it (Cloud Sync, if you have turned it on, is a separate feature that does publish finished events). But the assistant is usually a cloud service — when it answers a question, the event data it read is sent to that service to produce the answer, exactly as if you had pasted it into a chat window. Treat it the way you&#39;d treat sharing a start list.</p></blockquote><h2 id="turn-it-on" tabindex="-1">Turn it on <a class="header-anchor" href="#turn-it-on" aria-label="Permalink to &quot;Turn it on&quot;">​</a></h2><ol><li>Open <strong>Settings → AI assistants</strong> (under <strong>System</strong> in the left-hand list).</li><li>Switch on <strong>Allow AI assistants to connect</strong>.</li><li>Click <strong>Save</strong>.</li><li><strong>Restart the server.</strong> On the server computer you can do this from the tray / menu bar icon: <strong>Restart Server</strong>.</li></ol><p>The restart is required, and the page says so. Manager builds the assistant&#39;s address and the list of things it may do once, while starting — so a change only takes effect the next time it starts. That is deliberate: it means the rules can&#39;t shift underneath an assistant that&#39;s already connected mid-event.</p><p>The page shows the exact address to give your assistant, built from the address you&#39;re viewing Manager on — something like <code>http://localhost:5154/manager/mcp</code>.</p><h2 id="connect-your-assistant" tabindex="-1">Connect your assistant <a class="header-anchor" href="#connect-your-assistant" aria-label="Permalink to &quot;Connect your assistant&quot;">​</a></h2><p>Point your MCP client at the address shown on the settings page. In most apps this is a small configuration file:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;mesho-manager&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://localhost:5154/manager/mcp&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>If the assistant runs on a <strong>different computer</strong> to the server, use the server&#39;s LAN address instead of <code>localhost</code> — the same address volunteers use (see <a href="./server-addresses">Server addresses</a>).</p><p>Restart the assistant app after changing its configuration, then ask it something about your event. It works out which tools to use on its own; you don&#39;t have to name them.</p><h3 id="if-your-assistant-won-t-accept-the-address" tabindex="-1">If your assistant won&#39;t accept the address <a class="header-anchor" href="#if-your-assistant-won-t-accept-the-address" aria-label="Permalink to &quot;If your assistant won&#39;t accept the address&quot;">​</a></h3><p>Some assistants only accept an <code>https://</code> address, or can only start a local program rather than connect to one. The <strong>Claude desktop app</strong> is one of them: its <strong>Settings → Connectors → Add custom connector</strong> box will not take a plain <code>http://</code> address for a server on your own machine, so there is nothing useful to type there. It has to be added by hand to the app&#39;s own configuration file instead, as a program to launch rather than an address to dial.</p><p>There is a small connector for exactly this case. It runs on your computer, your assistant starts it, and it passes everything through to Manager — so the switches on this settings page still decide what the assistant can see and do.</p><p>It ships with the meshO Manager <strong>source code</strong> rather than with the installed app, so you need to fetch and build it once. This takes <a href="https://nodejs.org" target="_blank" rel="noreferrer">Node.js 20 or newer</a> and <a href="https://git-scm.com" target="_blank" rel="noreferrer">git</a>, and a terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/mesho-live/manager.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manager/tools/mesho-manager-mcp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>That leaves the connector at <code>manager/tools/mesho-manager-mcp/dist/index.js</code>. Note the full path — you need it below. (If a technical volunteer is setting Manager up for you, this is a reasonable thing to ask them to do.)</p><p>Then add the entry — in Claude Desktop, <strong>Settings → Developer → Edit Config</strong> opens the file (<code>claude_desktop_config.json</code>):</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;mesho-manager&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;node&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/absolute/path/to/manager/tools/mesho-manager-mcp/dist/index.js&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;env&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;MESHO_MANAGER_URL&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://localhost:5154&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>If you use an access PIN, add it here too:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      &quot;env&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;MESHO_MANAGER_URL&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://localhost:5154&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;MESHO_MANAGER_PIN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1234&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      }</span></span></code></pre></div><p>Quit and reopen the app afterwards — it reads that file only at start-up.</p><p>You do not need any of this if your assistant accepted the address above. Claude Code, for example, takes it directly:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --transport</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mesho-manager</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:5154/manager/mcp</span></span></code></pre></div><h2 id="if-you-use-an-access-pin" tabindex="-1">If you use an access PIN <a class="header-anchor" href="#if-you-use-an-access-pin" aria-label="Permalink to &quot;If you use an access PIN&quot;">​</a></h2><p>If you have set an access PIN (<strong>Settings → Access protection</strong>), MCP requires it too — an assistant cannot read your event without authenticating. MCP is protected on exactly the same terms as the rest of Manager&#39;s API, no more and no less.</p><p>If you have <strong>not</strong> set a PIN, MCP is open to anything that can reach the port, just as the rest of the API is. On a shared or public network, set a PIN before turning MCP on — especially with writes enabled.</p><p>Most assistants have nowhere to type a Manager PIN when you give them a plain address. The connector described above is the way round that: it logs in for them, so set <code>MESHO_MANAGER_PIN</code> in its <code>env</code> block and everything else works as normal. If the PIN is wrong you will see <em>&quot;meshO Manager rejected the access PIN (MESHO_MANAGER_PIN)&quot;</em> rather than a silent failure.</p><h2 id="letting-an-assistant-make-changes" tabindex="-1">Letting an assistant make changes <a class="header-anchor" href="#letting-an-assistant-make-changes" aria-label="Permalink to &quot;Letting an assistant make changes&quot;">​</a></h2><p>By default an assistant can <strong>only read</strong>. It cannot change anything, and the tools that would change something are not even offered to it — which is why <strong>Let assistants make changes</strong> stays greyed out until the first switch is on.</p><p><img src="`+o+'" alt="Both switches on, showing the warning about live edits"></p><p>With both switched on (and after a restart), an assistant can additionally:</p><ul><li><strong>Add and edit competitors</strong> — name, card number, class, club, bib, ranking, notes, start time, status</li><li><strong>Add and edit relay teams</strong>, including who runs which leg</li><li><strong>Add and edit classes</strong>, and choose which courses they run</li><li><strong>Add and edit courses</strong> — the control sequence, climb, length override, and how the course is scored, including a scatter course&#39;s required control count</li><li><strong>Add and edit controls</strong>, including marking one faulty mid-event</li><li><strong>Add and edit clubs</strong> in the event&#39;s club list</li><li>Bulk-set status for whole classes (the end-of-event &quot;mark everyone who never started as DNS&quot;)</li><li>Dismiss a dashboard status message</li><li><strong>Generate chase starts</strong> into a later stage of a carnival, from the standings so far</li><li><strong>Advance a knock-out round&#39;s field</strong> into the round&#39;s event</li><li><strong>Correct a standing</strong> — link two stages&#39; entries as one person, split them apart again, or drop one stage out of one competitor&#39;s total</li></ul><p>Between them, that&#39;s enough for an assistant to build an event&#39;s entries and reference data from scratch, or to fix them during one.</p><p>It <strong>cannot</strong> delete anything — no competitor, class, course, control, club, team or event. Deleting is an operator decision at the console, where you can see what else refers to the thing you&#39;re removing, and it is not offered to an assistant at all. Practically, that means a mistaken addition is yours to remove: an assistant can create a duplicate class but cannot tidy one away.</p><p>A few things are also left to you deliberately, because they aren&#39;t safe to do blind:</p><ul><li><strong>Forked courses</strong> (butterfly and relay variations) can&#39;t be created or reshaped — import them from a course file.</li><li><strong>Which download a runner is scored against</strong>, and <strong>overriding individual punches</strong>, stay at the console.</li><li><strong>Relay bibs</strong> aren&#39;t editable on the runner: they come from the team&#39;s bib and leg number, so change the team.</li><li><strong>Creating a carnival or a knock-out</strong>, attaching an event to it as a stage, and changing how it is scored all stay at the console. Each of them silently re-scores every stage already run.</li></ul><blockquote><p><strong>Warning:</strong> A live event happens once. An assistant making changes is editing the real event immediately, and every connected screen updates straight away. Leave writes off unless you specifically want this, and prefer turning them on after the event when you&#39;re tidying up results.</p></blockquote><p>Changes an assistant makes are ordinary Manager edits: they appear on every screen, and they&#39;re recorded in the event&#39;s audit trail just like an edit you made yourself, so you can always see what happened.</p><h2 id="turn-it-off" tabindex="-1">Turn it off <a class="header-anchor" href="#turn-it-off" aria-label="Permalink to &quot;Turn it off&quot;">​</a></h2><p>Switch off <strong>Allow AI assistants to connect</strong>, click <strong>Save</strong>, and restart the server. The address stops existing entirely — not merely refusing requests.</p><p>This switch covers <strong>every MCP</strong> route into your event, not just the address above — the connector included, since it only passes requests on to that same address, so once the address is gone it has nothing to talk to either. It does not cover Manager&#39;s ordinary web API, which is always on: an assistant with a general-purpose web-fetch tool can read that whether or not MCP is switched on. An access PIN is what closes that door.</p><h2 id="assistants-that-can-t-use-a-web-address" tabindex="-1">Assistants that can&#39;t use a web address <a class="header-anchor" href="#assistants-that-can-t-use-a-web-address" aria-label="Permalink to &quot;Assistants that can&#39;t use a web address&quot;">​</a></h2><p>A few MCP clients can only launch a program rather than connect to an address — the Claude desktop app among them. meshO ships a small connector for those, set up by hand in the assistant&#39;s own configuration file (see <a href="#if-your-assistant-wont-accept-the-address">If your assistant won&#39;t accept the address</a> above for the exact entry).</p><p>It&#39;s worth knowing it exists for one reason: it isn&#39;t a way around these switches. It simply passes the assistant&#39;s questions on to the address above, so it can only read what that address serves, and can only make changes when you&#39;ve allowed them. There is no second place to check.</p><h2 id="good-practice" tabindex="-1">Good practice <a class="header-anchor" href="#good-practice" aria-label="Permalink to &quot;Good practice&quot;">​</a></h2><ul><li><strong>Leave it off unless you&#39;re using it.</strong> It takes seconds to turn on when you need it.</li><li><strong>Reads first.</strong> Run without writes until you&#39;re confident, then enable writes only if you actually need the assistant to fix things.</li><li><strong>Set an event up before it&#39;s live.</strong> Building classes, courses and entries is much better suited to the day before than to the middle of a race, and mistakes cost nothing then.</li><li><strong>Check results claims.</strong> Manager tells the assistant when a class still has runners out, and a good assistant will repeat that — but always confirm from the results screen before publishing anything.</li><li><strong>Relay times.</strong> In a relay, an assistant reports each runner&#39;s <em>leg</em> time, not the team&#39;s cumulative time. If a number looks unexpectedly small for a relay, that&#39;s why.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>What to check</th></tr></thead><tbody><tr><td>The assistant can&#39;t connect</td><td>Did you <strong>restart the server</strong> after saving? The switch alone doesn&#39;t open the address.</td></tr><tr><td>The app refuses the address when adding a connector</td><td>It only takes <code>https://</code>. Use the connector instead — see <a href="#if-your-assistant-wont-accept-the-address">If your assistant won&#39;t accept the address</a>.</td></tr><tr><td>&quot;Not found&quot;, or a Manager page appears instead</td><td>Same thing — the setting is saved but the server hasn&#39;t restarted into it yet.</td></tr><tr><td>It connects but says there are no events</td><td>It&#39;s talking to a Manager with no events on it — check you used the right computer&#39;s address.</td></tr><tr><td>It can read but not change anything</td><td>That&#39;s the default. Switch on <strong>Let assistants make changes</strong>, save, and restart.</td></tr><tr><td>It&#39;s refused with an authorisation error</td><td>You have an access PIN set. See <a href="#if-you-use-an-access-pin">If you use an access PIN</a> above.</td></tr><tr><td>The <strong>AI assistants</strong> page isn&#39;t in Settings</td><td>Your Manager predates this feature — update to a newer version.</td></tr><tr><td>You turned it off but an assistant still answers</td><td>Check you <strong>restarted the server</strong> after saving — until then the address is still open. If you have, the assistant is most likely answering from what it read earlier in the same conversation rather than asking again; start a new conversation to confirm.</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./settings">Settings</a></li><li><a href="./multi-operator-setup">Multi-operator setup</a></li><li><a href="./status-and-race-time">Status and race time rules</a> — the rules an assistant is reporting when it explains a competitor&#39;s status</li><li><a href="./troubleshooting">Troubleshooting</a></li><li><a href="./backup-and-restore">Backup and restore</a> — worth having a backup before letting anything make bulk changes</li></ul>',64)])])}const y=s(r,[["render",h]]);export{k as __pageData,y as default};
